# README gets an append-only Phase 16 note so the migration is resilient to
# previous documentation edits.
readme = Path("README.md")
text = readme.read_text(encoding="utf-8")
marker = "## Phase 16 — Order Execution & Partial-Fill Reconciliation"
if marker not in text:
    text = text.rstrip() + '''\n\n## Phase 16 — Order Execution & Partial-Fill Reconciliation\n\nLive order submission now uses normalized execution receipts (`FILLED`, `PARTIAL`, `PLACED`) and explicit rejection vs ambiguous-submission exceptions. A persistent `pending_order_intent` is written to `live_state.json` before every entry/close/flatten submission and is cleared only after a fully confirmed fill and durable audit event. Partial fills, accepted-but-unconfirmed orders, missing submission results, fill-volume mismatches, and unexpected execution exceptions halt new trading without automatic resend or auto-repair. A leftover intent after restart is itself a CRITICAL fail-closed condition and requires broker-state reconciliation before manual clearance.\n'''
    readme.write_text(text, encoding="utf-8")
